-- Audit trail of every scoring rule that fired for a biopsy result.

CREATE TABLE biopsy_test_result_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    biopsy_test_result_grade_id UUID NOT NULL
        REFERENCES biopsy_test_result_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('classification', 'severity', 'completeness', 'follow-up', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_biopsy_test_result_grade_rule_grade_id
    ON biopsy_test_result_grade_rule(biopsy_test_result_grade_id);

CREATE TRIGGER trigger_biopsy_test_result_grade_rule_updated_at
    BEFORE UPDATE ON biopsy_test_result_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE biopsy_test_result_grade_rule IS
